use std::fs;
use std::path::Path;
use std::sync::mpsc;
use std::thread;
use ulw_loop_core::command_types::{CreateGoalsOptions, RecordEvidenceOptions};
use ulw_loop_core::paths::{ulw_loop_ledger_path, ulw_loop_state_lock_path, UlwLoopScope};
use ulw_loop_core::plan_io::read_ulw_loop_plan;
use ulw_loop_core::sdk::{AgentToolkit, ToolkitContext, ToolkitResponse};
use ulw_loop_core::surface::UlwLoopToolkitSurface;

fn make_context(dir: &Path, session: &str, surface: UlwLoopToolkitSurface) -> AgentToolkit { AgentToolkit::new(ToolkitContext { cwd: dir.display().to_string(), session_id: session.into(), surface }, None).expect("valid context") }
fn seed(dir: &Path, session: &str) -> (String, Vec<String>) { let tk = make_context(dir, session, UlwLoopToolkitSurface::LazyCodex); assert!(matches!(tk.create_goals(&CreateGoalsOptions { brief: "Session context fixture".into(), goals: None, codex_goal_mode: None, force: None, validation_batches_json: None }), ToolkitResponse::Success { .. })); let goal = match tk.complete_goals(None) { ToolkitResponse::Success { result: ulw_loop_core::plan_crud::StartNextResult::Started { goal, .. }, .. } => goal, _ => panic!() }; (goal.id, goal.success_criteria.into_iter().map(|c| c.id).collect()) }

#[test]
fn invalid_normalized_session_id_rejects_without_state() { let dir = tempfile::tempdir().unwrap(); let result = AgentToolkit::new(ToolkitContext { cwd: dir.path().display().to_string(), session_id: "../../x".into(), surface: UlwLoopToolkitSurface::OmoSenpi }, None); assert_eq!(result.err().unwrap().code, "ULW_LOOP_SESSION_ID_INVALID"); assert!(!dir.path().join(".omo/ulw-loop").exists()); }
#[test]
fn blank_session_id_reports_required_error() { let dir = tempfile::tempdir().unwrap(); let result = AgentToolkit::new(ToolkitContext { cwd: dir.path().display().to_string(), session_id: "   ".into(), surface: UlwLoopToolkitSurface::OmoSenpi }, None); assert_eq!(result.err().unwrap().code, "ULW_LOOP_SESSION_ID_REQUIRED"); }
#[test]
fn foreign_session_reads_fail_closed() { let dir = tempfile::tempdir().unwrap(); seed(dir.path(), "session-a"); let status = make_context(dir.path(), "session-b", UlwLoopToolkitSurface::LazyCodex).status(); assert!(matches!(status, ToolkitResponse::Failure { .. })); }
#[test]
fn mutation_waits_for_existing_state_lock() { let dir = tempfile::tempdir().unwrap(); let (goal, criteria) = seed(dir.path(), "session-lock"); let criterion = criteria[0].clone(); let lock = ulw_loop_state_lock_path(dir.path(), Some(&UlwLoopScope { session_id: Some("session-lock".into()), ..Default::default() })); fs::create_dir_all(lock.parent().unwrap()).unwrap(); fs::write(&lock, "{\"pid\":1}").unwrap(); let (ready_tx, ready_rx) = mpsc::channel(); let (release_tx, release_rx) = mpsc::channel(); let release = lock.clone(); let releaser = thread::spawn(move || { ready_tx.send(()).unwrap(); release_rx.recv().unwrap(); fs::remove_file(release).unwrap(); }); ready_rx.recv().unwrap(); let root = dir.path().to_path_buf(); let mutation = thread::spawn(move || make_context(&root, "session-lock", UlwLoopToolkitSurface::LazyCodex).record_evidence(&RecordEvidenceOptions { goal_id: goal, criterion_id: criterion, status: "pass".into(), evidence: "waited for the held lock".into(), notes: None, artifacts: None })); release_tx.send(()).unwrap(); let result = mutation.join().unwrap(); releaser.join().unwrap(); assert!(matches!(result, ToolkitResponse::Success { .. })); assert!(!lock.exists()); }
#[test]
fn concurrent_instances_keep_both_ledger_entries() { let dir = tempfile::tempdir().unwrap(); let (goal, criteria) = seed(dir.path(), "session-concurrent"); let root = dir.path().to_path_buf(); let g1 = goal.clone(); let c1 = criteria[0].clone(); let c2 = criteria[1].clone(); let first = thread::spawn(move || make_context(&root, "session-concurrent", UlwLoopToolkitSurface::LazyCodex).record_evidence(&RecordEvidenceOptions { goal_id: g1, criterion_id: c1, status: "pass".into(), evidence: "first instance".into(), notes: None, artifacts: None })); let root2 = dir.path().to_path_buf(); let g2 = goal; let second = thread::spawn(move || make_context(&root2, "session-concurrent", UlwLoopToolkitSurface::LazyCodex).record_evidence(&RecordEvidenceOptions { goal_id: g2, criterion_id: c2, status: "pass".into(), evidence: "second instance".into(), notes: None, artifacts: None })); assert!(matches!(first.join().unwrap(), ToolkitResponse::Success { .. })); assert!(matches!(second.join().unwrap(), ToolkitResponse::Success { .. })); let ledger = fs::read_to_string(ulw_loop_ledger_path(dir.path(), Some(&UlwLoopScope { session_id: Some("session-concurrent".into()), ..Default::default() }))).unwrap(); assert!(ledger.contains("C001")); assert!(ledger.contains("C002")); let _ = read_ulw_loop_plan(dir.path(), Some(&UlwLoopScope { session_id: Some("session-concurrent".into()), ..Default::default() })).unwrap(); }
